  setpath($cfg,['ai','azure_image','endpoint'],rtrim(trim((string)($_POST['azure_image_endpoint']??'')),'/'));
  setpath($cfg,['ai','azure_image','model'],trim((string)($_POST['azure_image_model']??'MAI-Image-2.5')));
  $azureTranslatorKey=trim((string)($_POST['azure_translator_api_key']??''));
  if($azureTranslatorKey!=='')setpath($cfg,['ai','azure_translator','api_key'],$azureTranslatorKey);
  setpath($cfg,['ai','azure_translator','endpoint'],rtrim(trim((string)($_POST['azure_translator_endpoint']??'https://api.cognitive.microsofttranslator.com')),'/'));
  setpath($cfg,['ai','azure_translator','region'],trim((string)($_POST['azure_translator_region']??'')));
  setpath($cfg,['voice','openai_voice'],trim((string)($_POST['openai_voice']??'coral')));
  foreach(['en-US','fr-FR','fr-CA','es-ES','ht-HT','en-JM','ln-CD'] as $loc){$v=trim((string)($_POST['voice_'.str_replace('-','_',$loc)]??''));if($v!==''){setpath($cfg,['narration','elevenlabs','voices',$loc],$v);setpath($cfg,['voice','voices',$loc],$v);}}
  foreach(['en-US','fr-FR','fr-CA','es-ES','it-IT','de-DE','ru-RU','pt-PT','ar-MA','ar-EG','sw-KE'] as $loc){$v=trim((string)($_POST['azure_voice_'.str_replace('-','_',$loc)]??''));if($v!=='')setpath($cfg,['narration','azure','voices',$loc],$v);}
  $php="<?php\ndeclare(strict_types=1);\n/* Protected live configuration. Keep beside public_html. */\nreturn ".var_export($cfg,true).";\n";$tmp=$file.'.tmp';if(file_put_contents($tmp,$php,LOCK_EX)===false||!rename($tmp,$file))throw new RuntimeException('Could not update protected configuration.');@chmod($file,0600);$msg='Premium voice settings saved.';
 }catch(Throwable $e){$err=$e->getMessage();}
}
